<?php
namespace App\Http\Requests\Tenant;use App\Domain\AI\Knowledge\Data\{KnowledgeContentData,KnowledgeSourceName};use App\Domain\AI\Knowledge\Enums\KnowledgeSourceType;use App\Domain\Network\Tenancy\TenantAccessService;use Illuminate\Foundation\Http\FormRequest;use Illuminate\Validation\Rule;use Illuminate\Validation\Validator;
abstract class KnowledgeContentRequest extends FormRequest{protected const FRAMEWORK=['_token'];abstract protected function includesName():bool;public function authorize():bool{return app(TenantAccessService::class)->canManageTenant($this->user());}protected function prepareForValidation():void{$clean=function($v)use(&$clean){if(is_array($v))return array_map($clean,$v);return is_string($v)?trim($v):$v;};$this->replace($clean($this->all()));}public function rules():array{$rules=['type'=>['required',Rule::enum(KnowledgeSourceType::class)],'body'=>['nullable','string','max:20000'],'entries'=>['nullable','array','min:1','max:50'],'entries.*'=>['array'],'entries.*.question'=>['required_with:entries','string','max:500'],'entries.*.answer'=>['required_with:entries','string','max:4000']];if($this->includesName())$rules=['name'=>['required','string','max:160',function(string$attribute,mixed$value,\Closure$fail){try{KnowledgeSourceName::from($value);}catch(\InvalidArgumentException){$fail('El nombre de la fuente no es válido.');}}]]+$rules;return$rules;}public function withValidator(Validator$v):void{$v->after(function(Validator$v){$allowed=array_merge(array_keys($this->rules()),self::FRAMEWORK);foreach(array_keys($this->all())as$key)if(!in_array($key,$allowed,true))$v->errors()->add($key,'Este campo no está permitido.');if($v->errors()->isNotEmpty())return;try{$this->knowledgeData();}catch(\InvalidArgumentException){$v->errors()->add('content','El contenido no cumple el formato permitido.');}});}public function knowledgeData():KnowledgeContentData{$type=(string)$this->validated('type');return KnowledgeContentData::fromArray($type==='faq'?['type'=>$type,'entries'=>$this->validated('entries')]:['type'=>$type,'body'=>$this->validated('body')]);}}
